-- Index audit 2026-10-22. This is the only index in the bot schema that served
-- neither a constraint nor a query. Client numbers are generated by the
-- bvk_client_numbers_number_seq sequence, so uniqueness is already guaranteed;
-- every lookup resolves a client by client_id, never by number. UNIQUE was
-- declared inline in migration 009, so the constraint has to go with its index.
ALTER TABLE bvk_client_numbers DROP CONSTRAINT IF EXISTS bvk_client_numbers_number_key;
DROP INDEX IF EXISTS bvk_client_numbers_number_key;
